import AppKit

// MARK: - Transient Pasteboard Utility
// Manages atomic clipboard writes with privacy & transient markers to prevent
// clipboard history managers (Raycast, Maccy, Paste, 1Password, Alfred) from
// recording automated text replacements and autocompletions.

public enum TransientPasteboard {

    /// Standard transient, private, and auto-generated pasteboard types recognized by macOS clipboard utilities.
    public static let transientTypes: [NSPasteboard.PasteboardType] = [
        .string,
        NSPasteboard.PasteboardType("org.nspasteboard.TransientType"),
        NSPasteboard.PasteboardType("org.nspasteboard.AutoGeneratedType"),
        NSPasteboard.PasteboardType("org.nspasteboard.ConcealedType"),
        NSPasteboard.PasteboardType("com.apple.quicktype.save-state"),
        NSPasteboard.PasteboardType("de.petermaurer.TransientPasteboardType")
    ]

    /// Atomically writes text with transient markers into the pasteboard.
    /// Returns the new pasteboard change count.
    @discardableResult
    public static func writeString(_ text: String, pasteboard: NSPasteboard = .general) -> Int {
        pasteboard.clearContents()
        let item = NSPasteboardItem()
        item.setString(text, forType: .string)
        for type in transientTypes where type != .string {
            item.setString("", forType: type)
        }
        pasteboard.writeObjects([item])
        return pasteboard.changeCount
    }

    /// Captures a complete snapshot of all items, types, and raw data on the pasteboard.
    public static func snapshot(pasteboard: NSPasteboard = .general) -> [[(NSPasteboard.PasteboardType, Data)]] {
        pasteboard.pasteboardItems?.map { item in
            item.types.compactMap { type in
                item.data(forType: type).map { (type, $0) }
            }
        } ?? []
    }

    /// Restores a previously captured clipboard snapshot.
    public static func restore(_ snapshot: [[(NSPasteboard.PasteboardType, Data)]], pasteboard: NSPasteboard = .general) {
        pasteboard.clearContents()
        guard !snapshot.isEmpty else { return }
        for itemData in snapshot {
            let item = NSPasteboardItem()
            for (type, data) in itemData {
                item.setData(data, forType: type)
            }
            pasteboard.writeObjects([item])
        }
    }
}
